<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\TenantLoginProviderCertificateVO;

trait TenantLoginProviderCertificateAttributeHolder
{
    protected TenantLoginProviderCertificateVO|string|null $certificate = null;
    protected bool $certificateAssigned = false;

    public function getCertificateOrCurrent(?TenantLoginProviderCertificateVO $certificate): ?TenantLoginProviderCertificateVO
    {
        return $this->certificateAssigned ? ($this->certificate === null ? null : TenantLoginProviderCertificateVO::from($this->certificate)) : $certificate;
    }
    public function certificateTryBuildInitial(ConstraintFailList $error): ?TenantLoginProviderCertificateVO
    {
        return  TenantLoginProviderCertificateVO::tryFrom($this->certificateAssigned ? $this->certificate : null, $error);
    }
    public function certificate(TenantLoginProviderCertificateVO|string|null $certificate): static
    {
        $this->certificate = $certificate;
        $this->certificateAssigned = true;
        return $this;
    }
    public function getCertificate(): ?string
    {
        return $this->certificate instanceof TenantLoginProviderCertificateVO ? $this->certificate->value() : $this->certificate;
    }
    public function isCertificateAssigned(): bool
    {
        return $this->certificateAssigned;
    }
    public function writeCertificateTo(mixed $att): void
    {
        if ($this->certificateAssigned) {
            $att->certificate($this->certificate);
        }
    }
    public function readCertificateFrom(mixed $att): void
    {
        if ($att->isCertificateAssigned()) {
            $certificate = $att->getCertificate();
            $this->certificate($certificate);
        }
    }
    public function unsetCertificate(): static
    {
        $this->certificateAssigned = false;
        return $this;
    }
    protected function withDefaultCertificate(): void
    {
    }
    protected function withAssertedCertificateRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->certificateAssigned = $this->certificateAssigned) {
            $value->certificate = TenantLoginProviderCertificateVO::tryFrom($this->certificate, $errorsList);
        }
    }
}
